// ORDINAL(宣言順の番号)で保存していたら……を再現する
// 「保存したとき」の enum
enum StatusV1 { DRAFT, SUBMITTED, APPROVED, RETURNED, WITHDRAWN }
// 半年後、誰かが「確認中」を DRAFT の次に足した enum
// ここを変えてみよう:CHECKING を末尾に移す/定数を1つ削除してみる
enum StatusV2 {
    DRAFT, CHECKING, SUBMITTED, APPROVED, RETURNED, WITHDRAWN
}

// DB には V1 の時代に保存した値が残っている
StatusV1[] saved = {
    StatusV1.SUBMITTED, StatusV1.APPROVED, StatusV1.WITHDRAWN };

for (StatusV1 s : saved) {
    int ordinalInDb = s.ordinal();   // ORDINAL で保存された番号
    String nameInDb = s.name();      // STRING で保存された名前
    StatusV2 byOrdinal = StatusV2.values()[ordinalInDb];
    StatusV2 byName = StatusV2.valueOf(nameInDb);
    System.out.printf("保存時 %-10s → ORDINAL(%d)で読むと %-10s",
            s, ordinalInDb, byOrdinal);
    System.out.println(" / STRING で読むと " + byName);
}

import java.time.LocalDateTime;
import org.springframework.data.repository.query.parser.Part;
import org.springframework.data.repository.query.parser.PartTree;

// 承認くんの申請エンティティ(DB には繋がない。プロパティ名だけ使う)
class Employee { Long id; String name; String email; }
class ApprovalRequest {
    Long id; String title; Integer amount; String status;
    Employee applicant; Employee approver;
    LocalDateTime createdAt; LocalDateTime submittedAt;
}

// ここを変えてみよう:メソッド名を書き換えて再実行
// (Desc を Asc に・Top5 を付ける・わざと submitedAt と書く など)
String[] names = {
    "findByApplicantOrderByCreatedAtDesc",
    "findByStatusOrderBySubmittedAtAsc",
    "countByStatus",
    "findByApplicantNameAndAmountGreaterThanEqual",
    "findByStatusOrderBySubmitedAtAsc",
};

for (String name : names) {
    System.out.println("■ " + name);
    try {
        PartTree tree = new PartTree(name, ApprovalRequest.class);
        for (PartTree.OrPart or : tree) {
            for (Part p : or) {
                System.out.println("  条件: " + p.getProperty().toDotPath()
                        + " " + p.getType());
            }
        }
        System.out.println("  並び順: " + tree.getSort()
                + " / count: " + tree.isCountProjection());
    } catch (RuntimeException e) {
        System.out.println("  起動時エラーになる: " + e.getMessage());
    }
}

